async function put(root,file,content=''){await mkdir(path.dirname(path.join(root,file)),{recursive:true});await writeFile(path.join(root,file),content);}
async function fixture(){const root=await mkdtemp(path.join(tmpdir(),'time-release-v5-test-'));for(const file of REQUIRED_FILES)await put(root,file,file.endsWith('Cargo.lock')?LOCK:file.endsWith('.json')?'{}\n':'');for(const dir of SOURCE_DIRS)await put(root,dir+'/lib.rs','// fixture\n');await put(root,'v5/tests/common/mod.rs','// shared test helpers\n');await put(root,'deploy/Dockerfile','FROM ${RUST_IMAGE}\n');await put(root,'deploy/Dockerfile.v5','FROM ${RUST_IMAGE}\n');await put(root,'deploy/example.json','{}');for(const file of TOOL_FILES)await put(root,file,file.endsWith('.json')?'{}\n':'// fixture');return root;}
// Exactly the fixture of tools/release-v4.test.mjs.
async function v4Fixture(){const root=await mkdtemp(path.join(tmpdir(),'time-release-test-'));for(const file of v4.REQUIRED_FILES)await put(root,file,file.endsWith('Cargo.lock')?LOCK:file.endsWith('.json')?'{}\n':'');for(const dir of ['src','v2/src','v4/src','pos/src','treasury/src','bitcoin-bridge/src','history/src','registration/src','v2/tests','v4/tests','pos/tests','treasury/tests','bitcoin-bridge/tests','registration/tests'])await put(root,dir+'/lib.rs','// fixture\n');await put(root,'deploy/Dockerfile','FROM ${RUST_IMAGE}\n');await put(root,'deploy/example.json','{}');await put(root,'tools/release-v4.mjs','// fixture');await put(root,'tools/release-v4.test.mjs','// fixture');return root;}
async function nativeEvidence(nativeDirectory,native){const artifact={release_id:native.release_id,image_id:'sha256:'+hash,platform:native.platform,binaries:[],sbom_sha256:native.sbom_sha256,image_pins:pins};await put(nativeDirectory,'linux-build-smoke.json',JSON.stringify({...artifact,artifact_identity_sha256:sha256(Buffer.from(JSON.stringify(artifact))),status:'PASS_BUILD_AND_VERSION_ONLY'}));const source_files=native.source_files.filter(file=>!file.path.startsWith('deploy/')&&!file.path.startsWith('tools/')&&!file.path.startsWith('consensus/'));await put(nativeDirectory,'linux-native-validation/report.json',JSON.stringify({release_id:native.release_id,status:'PASS_LINUX_NATIVE_TESTS_AND_CLIPPY',source_files,host_context_unchanged:true,source_checks_after_present:true}));}
async function nativeFixture(){const root=await fixture();for(const file of CLIENT_FILES)await put(root,file,file.endsWith('.json')?'{}':'// public runtime fixture');const nativeDirectory=path.join(root,'releases','native'),native=await createRelease({root,out:nativeDirectory,imagePins:pins});await nativeEvidence(nativeDirectory,native);return{root,nativeDirectory,out:path.join(root,'releases','distribution')};}
function authority(roles=REQUIRED_GATES,organization='external-review'){const pair=generateKeyPairSync('ed25519'),pub=pair.publicKey.export({format:'der',type:'spki'}).subarray(-32).toString('hex');return{pair,trust:{release_organization:'release-author',authorities:[{id:'auditor',organization,roles,public_key_hex:pub}]},attest:payload=>({issuer:'auditor',payload,signature:sign(null,signingBytes(payload),pair.privateKey).toString('base64')})};}
function manifest(engine='v5'){const value={schema_version:2,protocol_version:4,...(engine==='v5'?{engine:'v5'}:{}),platform:'linux/amd64',image_pins:pins,source_files:[],generated_dockerignore_sha256:hash,binaries:[],evidence:[],sbom_sha256:hash};return{...value,release_id:sha256(Buffer.from(JSON.stringify(value))),status:'DEVELOPMENT_CANDIDATE',public_funds_allowed:false,mainnet_receipts_enabled:false,monetary_enable_toggle:false};}
const v5Status=(extra={})=>({app_version:'4',engine:'v5',mode:'devnet',public_launch_allowed:false,authenticated:false,root:hash,maintenance:{pressure:false,eligible_work_pending:false,snapshot_height:'8',oldest_queryable_version:'1'},...extra});
const elf=(machine=62)=>{const bytes=Buffer.alloc(64);bytes[0]=127;bytes.write('ELF',1,'ascii');bytes.writeUInt16LE(machine,18);return bytes;};
async function guardSetup(m=manifest()){const root=await fixture(),a=authority(['signer_lease']);const genesis={chain_id:'time-devnet-v4-test',app_state:{ledger:{chain_id:'time-devnet-v4-test'},bitcoin:{mainnet_receipts_enabled:false},validators:[{consensus_key:key}]}};await put(root,'operator/genesis.json',JSON.stringify(genesis));await put(root,'operator/release.json',JSON.stringify(m));await put(root,'operator/trust.json',JSON.stringify(a.trust));const settings={release_manifest:path.join(root,'operator/release.json'),release_id:m.release_id,genesis_file:path.join(root,'operator/genesis.json'),genesis_sha256:sha256(Buffer.from(JSON.stringify(genesis))),chain_id:genesis.chain_id,validator_public_key_hex:key,signer_identity:'fenced-hsm',trust_file:path.join(root,'operator/trust.json'),signer_lease_file:path.join(root,'operator/lease.json'),sentry_peers:['a'.repeat(40)+'@one:26656','b'.repeat(40)+'@two:26656']};const payload={kind:'signer_lease',release_id:m.release_id,genesis_sha256:settings.genesis_sha256,chain_id:settings.chain_id,validator_public_key_hex:key,signer_identity:settings.signer_identity,...(m.engine?{engine:m.engine}:{}),enforcement:'EVERY_SIGNATURE',fence_domain:'authority',fence_token:'42',lease_id:'unique',...times};await put(root,'operator/lease.json',JSON.stringify(a.attest(payload)));return{root,a,settings,payload};}

// The v4 safety cases, applied to the v5 release.
test('v5: path traversal, Windows drive, runtime and secret names are rejected',()=>{for(const value of ['../src/x.rs','src/../x.rs','/tmp/x','C:/x','src\\x.rs','.local/x','foo/.tools/x','foo/.LOCAL/x','foo/.TOOLS/x','deploy/.env','deploy/priv_key.pem','deploy/secret.json','deploy/seed.txt','src//x.rs','v5/target/release/time-node-v5','v5/tests/../src/x.rs','v5/tests/secret.rs'])assert.throws(()=>safeRelative(value));assert.equal(safeRelative('v5/src/engine.rs'),'v5/src/engine.rs');assert.equal(safeRelative('v5/tests/common/mod.rs'),'v5/tests/common/mod.rs');});
test('v5: all base image inputs and runtime images require digests',async()=>{assert.equal(validateImagePins(pins),pins);for(const name of ['rust','go','runtime'])assert.throws(()=>validateImagePins({...pins,[name]:'node:latest'}));assert.throws(()=>checkEnvironment({TIME_IMAGE:pins.runtime,REMOTE_SIGNER_IMAGE:'signer:latest'}));assert.equal(checkEnvironment({TIME_IMAGE:pins.runtime,REMOTE_SIGNER_IMAGE:pins.go,OPERATOR_CONFIG:path.resolve('/operator'),SIGNER_CONFIG:path.resolve('/signer')}),true);const root=await fixture();await assert.rejects(createRelease({root,out:path.join(root,'releases','x'),imagePins:{...pins,rust:'rust:1.99.1'}}),/digest/);});
test('v5: Docker ignore control/glob injection cannot become a source filename',()=>{for(const file of ['deploy/x.json\n!.local/key','deploy/[x].json','deploy/*.json','deploy/!include.json','deploy/#rule.json','deploy/file\r.json','v5/src/x.rs\n!v5/target'])assert.throws(()=>safeRelative(file));});
test('v5: hardlink alias cannot pull unrelated contents into source allowlist',async()=>{for(const target of ['deploy/linked.mjs','v5/src/linked.rs','v5/tests/common/linked.rs']){const root=await fixture(),outside=await mkdtemp(path.join(tmpdir(),'time-hardlink-v5-'));await put(outside,'unrelated.rs','// unrelated');await link(path.join(outside,'unrelated.rs'),path.join(root,target));await assert.rejects(collectReleaseFiles(root),/single-link/);}});
test('v5: packager ignores private runtime directories; context has only allowlisted bytes',async()=>{const root=await fixture();await put(root,'.local/priv_key.json','SENSITIVE-LOCAL-DATA');await put(root,'.tools/cookie','SENSITIVE-COOKIE');await put(root,'v5/target/release/time-node-v5','SENSITIVE-TARGET');await put(root,'v5/README.md','not a build input');const out=path.join(root,'releases','candidate');const result=await createRelease({root,out,imagePins:pins});assert.equal(result.engine,'v5');assert.equal(releaseEngine(result),'v5');assert.equal(result.public_funds_allowed,false);assert.equal(result.mainnet_receipts_enabled,false);assert.equal(result.monetary_enable_toggle,false);assert.ok(Object.values(result.external_gates).every(v=>!v.includes('PASS')));const paths=result.source_files.map(f=>f.path);assert.ok(paths.every(f=>!/[.]local|[.]tools|target/.test(f)));for(const required of ['v5/Cargo.toml','v5/Cargo.lock','v5/src/lib.rs','v5/tests/lib.rs','v5/tests/common/mod.rs','v4/Cargo.toml','v4/src/lib.rs','v2/src/lib.rs','deploy/Dockerfile.v5','campaign/lib/genesis.mjs','tools/release-v5.mjs','tools/release-v5.test.mjs','tools/release-v4.mjs','tools/release-v4.test.mjs','tools/fixtures/release-v4-native-linux-final-003b.json'])assert.ok(paths.includes(required),required);assert.ok(!paths.includes('deploy/Dockerfile'));assert.ok(!paths.includes('v5/README.md'));const ignored=await readFile(path.join(out,'context','.dockerignore'),'utf8');assert.ok(ignored.startsWith('**\n!**/\n'));assert.ok(!ignored.includes('SENSITIVE'));assert.equal(validateRelease(result).release_id,result.release_id);await assert.rejects(createRelease({root,out,imagePins:pins}),/preserved/);const sbom=JSON.parse(await readFile(path.join(out,'sbom.spdx.json'),'utf8'));assert.equal(sbom.spdxVersion,'SPDX-2.3');assert.ok(sbom.name.startsWith('timecurrency-v5-source-'));assert.deepEqual(sbom.creationInfo.creators,['Tool: timecurrency-release-v5']);assert.equal(sha256(await readFile(path.join(out,'sbom.spdx.json'))),result.sbom_sha256);});
test('v5: secret input filename rejects whole packaging before output creation',async()=>{for(const file of ['deploy/secret.json','v5/tests/secret.rs','v5/src/seed.rs']){const root=await fixture();await put(root,file,'{}');await assert.rejects(collectReleaseFiles(root),/Forbidden/);}});
test('v5: identical inputs produce identical source and SBOM identity, independent of output directory',async()=>{const root=await fixture();const a=await createRelease({root,out:path.join(root,'releases','a'),imagePins:pins}),b=await createRelease({root,out:path.join(root,'releases','b'),imagePins:{runtime:pins.runtime,go:pins.go,rust:pins.rust}});assert.equal(a.release_id,b.release_id);assert.equal(a.sbom_sha256,b.sbom_sha256);assert.throws(()=>validateRelease({...a,sbom_sha256:key}),/identity/);});
test('v5: combined distribution uses only exact SDK runtime allowlist and preserves native scope/gates',async()=>{const root=await fixture();for(const file of CLIENT_FILES)await put(root,file,file.endsWith('.json')?'{}':'// public runtime fixture');await put(root,'client-v4/test-ca.pem','must never include');await put(root,'client-v4/account-security.test.mjs','must never include');await put(root,'client-v4/own-node.test.mjs','must never include');await put(root,'web-v4/wallet/tests/fixture.json','must never include');const nativeDirectory=path.join(root,'releases','native');const native=await createRelease({root,out:nativeDirectory,imagePins:pins});await nativeEvidence(nativeDirectory,native);const out=path.join(root,'releases','distribution'),result=await createSdkDistribution({root,nativeDirectory,out});assert.equal(result.engine,'v5');assert.equal(result.public_funds_allowed,false);assert.equal(result.native_release_id,native.release_id);const sdk=result.sdk_files.map(file=>file.path);assert.ok(sdk.every(file=>!file.includes('test-ca')&&!file.includes('/tests/')&&!file.endsWith('.test.mjs')));for(const file of ['client-v4/account-security.mjs','client-v4/own-node.mjs','client-v4/server-auth.mjs','client-v4/server.mjs','deploy/gateway/start.mjs'])assert.ok(sdk.includes(file),file);assert.equal(result.sdk_files.length,CLIENT_FILES.length);assert.ok(result.packaging_tools.some(file=>file.path==='tools/release-v5.mjs'));assert.equal(result.external_gates.independent_security_review,'OUTSTANDING_SIGNED_ATTESTATION_REQUIRED');await assert.rejects(createSdkDistribution({root,nativeDirectory,out}),/preserved/);});
test('v5: combined distribution refuses missing native component evidence',async()=>{const root=await fixture(),nativeDirectory=path.join(root,'releases','native');await createRelease({root,out:nativeDirectory,imagePins:pins});await assert.rejects(createSdkDistribution({root,nativeDirectory,out:path.join(root,'releases','sdk')}));});
test('v5: native JSON artifact credentials are rejected before distribution output is created',async()=>{for(const file of ['release.json','sbom.spdx.json','linux-build-smoke.json','linux-native-validation/report.json']){const value=await nativeFixture(),location=path.join(value.nativeDirectory,file),parsed=JSON.parse(await readFile(location,'utf8'));await writeFile(location,JSON.stringify({...parsed,private_key:'SENSITIVE-TEST-MARKER'}));await assert.rejects(createSdkDistribution(value),/credential/);await assert.rejects(lstat(value.out),{code:'ENOENT'});}});
test('v5: native artifact and Docker allowlist hardlinks are rejected before copying bytes',async()=>{for(const file of ['release.json','sbom.spdx.json','linux-build-smoke.json','linux-native-validation/report.json','context/.dockerignore']){const value=await nativeFixture(),location=path.join(value.nativeDirectory,file),outside=path.join(value.root,'unrelated-public-input');await writeFile(outside,await readFile(location));await unlink(location);await link(outside,location);await assert.rejects(createSdkDistribution(value),/single-link/);await assert.rejects(lstat(value.out),{code:'ENOENT'});}});
test('v5: native artifact directory symlink or junction is refused before output creation',async t=>{const value=await nativeFixture(),location=path.join(value.nativeDirectory,'linux-native-validation'),saved=location+'-saved';await rename(location,saved);try{await symlink(saved,location,process.platform==='win32'?'junction':'dir');}catch(error){if(error.code==='EPERM'){t.skip('OS cannot create directory links');return;}throw error;}await assert.rejects(createSdkDistribution(value),/Symlink/);await assert.rejects(lstat(value.out),{code:'ENOENT'});});
test('v5: Linux build guard rejects changed context and SBOM before invoking Docker',async()=>{const root=await fixture(),out=path.join(root,'releases','a');await createRelease({root,out,imagePins:pins});await writeFile(path.join(out,'sbom.spdx.json'),'{}');await assert.rejects(buildCandidate(out,'test:candidate'),/SBOM/);await put(out,'context/v5/src/lib.rs','// altered');await assert.rejects(buildCandidate(out,'test:candidate'),/source digest/);const second=path.join(root,'releases','b');await createRelease({root,out:second,imagePins:pins});await put(second,'context/deploy/Dockerfile.v5','FROM scratch\n');await assert.rejects(buildCandidate(second,'test:candidate'),/source digest/);});
test('v5: private PEM and private JSON fields cannot enter release sources',async()=>{const root=await fixture();await put(root,'deploy/example.json',JSON.stringify({priv_key:{value:'sensitive'}}));await assert.rejects(collectReleaseFiles(root),/credential/);await put(root,'deploy/example.json',JSON.stringify({data:'-----BEGIN '+'PRIVATE KEY-----'}));await assert.rejects(collectReleaseFiles(root),/credential/);const second=await fixture();await put(second,'v5/tests/common/mod.rs','// -----BEGIN '+'PRIVATE KEY-----');await assert.rejects(collectReleaseFiles(second),/credential/);});
test('v5: unsupported extra files, nested output runtime path and traversal fail closed',async()=>{const root=await fixture();await put(root,'unlisted.txt','no');await put(root,'v5/README.md','no');await assert.rejects(collectReleaseFiles(root,['unlisted.txt']),/allowlist/);await assert.rejects(collectReleaseFiles(root,['v5/README.md']),/allowlist/);await assert.rejects(collectReleaseFiles(root,['../outside']),/path/);for(const out of [root,path.join(root,'.local'),path.join(root,'releases','.tools','out'),path.join(root,'v4','src','out'),path.join(root,'v5','src','out'),path.join(root,'v5','tests','out')])await assert.rejects(createRelease({root,out,imagePins:pins}));});
test('v5: symlink/junction source, output ancestor and admitted binary ancestors reject',async t=>{const root=await fixture(),outside=await mkdtemp(path.join(tmpdir(),'time-release-v5-outside-'));try{await symlink(outside,path.join(root,'v5','src','linked'),process.platform==='win32'?'junction':'dir');}catch(error){if(error.code==='EPERM'){t.skip('OS cannot create symlink');return;}throw error;}await assert.rejects(collectReleaseFiles(root),/Symlink/);const root2=await fixture();await symlink(outside,path.join(root2,'releases'),process.platform==='win32'?'junction':'dir');await assert.rejects(createRelease({root:root2,out:path.join(root2,'releases','out'),imagePins:pins}),/Symlink/);const root3=await fixture();await put(outside,'time-node-v5',elf());await symlink(outside,path.join(root3,'build'),process.platform==='win32'?'junction':'dir');await assert.rejects(createRelease({root:root3,out:path.join(root3,'releases','out'),imagePins:pins,binaries:{'time-node-v5':path.join(root3,'build','time-node-v5')}}),/Symlink/);});
test('v5: Windows executable cannot be mislabeled as Linux artifact; only v5 binary names are admitted',async()=>{const root=await fixture();await put(root,'build/time-node-v5',Buffer.from('MZ'));await assert.rejects(createRelease({root,out:path.join(root,'releases','out'),imagePins:pins,binaries:{'time-node-v5':path.join(root,'build/time-node-v5')}}),/Linux/);await put(root,'build/arm',elf(183));await assert.rejects(createRelease({root,out:path.join(root,'releases','arm'),imagePins:pins,binaries:{'time-node-v5':path.join(root,'build/arm')}}),/architecture/);await put(root,'build/time-node-v4',elf());await assert.rejects(createRelease({root,out:path.join(root,'releases','v4name'),imagePins:pins,binaries:{'time-node-v4':path.join(root,'build/time-node-v4')}}),/Unsupported executable/);await put(root,'build/node',elf());const result=await createRelease({root,out:path.join(root,'releases','ok'),imagePins:pins,binaries:{'time-node-v5':path.join(root,'build/node')}});assert.deepEqual(result.binaries.map(b=>b.name),['time-node-v5']);assert.equal(validateRelease(result).release_id,result.release_id);});
test('v5: source mutation and tampered manifest change release identity',async()=>{const root=await fixture();const a=await createRelease({root,out:path.join(root,'releases','a'),imagePins:pins});await put(root,'v5/src/lib.rs','// changed');const b=await createRelease({root,out:path.join(root,'releases','b'),imagePins:pins});assert.notEqual(a.release_id,b.release_id);await put(root,'v5/Cargo.lock',LOCK+'\n[[package]]\nname = "other"\nversion = "2.0.0"\n');const c=await createRelease({root,out:path.join(root,'releases','c'),imagePins:pins});assert.notEqual(b.release_id,c.release_id);assert.notEqual(b.sbom_sha256,c.sbom_sha256);assert.throws(()=>validateRelease({...b,source_files:[]}));const{engine,...asV4}=b;assert.equal(engine,'v5');assert.throws(()=>validateRelease(asV4),/identity/);});
test('v5: CSPRNG enrollment has unique separate valid keypairs and exclusive output',async()=>{const parent=await mkdtemp(path.join(tmpdir(),'time-enrollment-v5-')),directory=path.join(parent,'operator');const pub=await generateOperatorKeys(directory),second=await generateOperatorKeys(path.join(parent,'second'));assert.notEqual(pub.consensus_public_key_hex,second.consensus_public_key_hex);const secret=JSON.parse(await readFile(path.join(directory,'consensus-enrollment.json'),'utf8')),node=JSON.parse(await readFile(path.join(directory,'node-identity.json'),'utf8'));const bytes=Buffer.from(secret.priv_key.value,'base64');assert.equal(bytes.length,64);const privateDer=Buffer.concat([Buffer.from('302e020100300506032b657004220420','hex'),bytes.subarray(0,32)]);assert.equal(createPublicKey({key:privateDer,type:'pkcs8',format:'der'}).export({format:'der',type:'spki'}).subarray(-32).toString('hex'),pub.consensus_public_key_hex);assert.notEqual(node.priv_key.value,secret.priv_key.value);await assert.rejects(generateOperatorKeys(directory),/preserved/);if(process.platform!=='win32')assert.equal((await lstat(path.join(directory,'consensus-enrollment.json'))).mode&0o777,0o600);});
test('v5: signed claims are bound to pinned issuer, role, exact context and expiry',()=>{const m=manifest(),a=authority(['signer_lease']),payload={kind:'signer_lease',release_id:m.release_id,...times},claim=a.attest(payload);assert.equal(signed(claim,a.trust,{kind:'signer_lease',release_id:m.release_id},now).payload,payload);assert.throws(()=>signed({...claim,payload:{...payload,release_id:manifest('v4').release_id}},a.trust,{kind:'signer_lease'},now),/Invalid signed/);assert.throws(()=>signed(claim,a.trust,{kind:'signer_lease',release_id:manifest('v4').release_id},now),/scope/);assert.throws(()=>signed(claim,{authorities:[]},{kind:'signer_lease'},now),/authority/);assert.throws(()=>signed(claim,a.trust,{kind:'signer_lease'},now+120000),/expired/);});
test('v5: candidate gates remain outstanding without independent signed evidence',()=>{const m=manifest(),a=authority();const missing=checkLaunch(m,a.trust,[],hash,now);assert.equal(missing.status,'CANDIDATE_BLOCKED_EXTERNAL_GATES');assert.equal(missing.release_id,m.release_id);const self=authority(REQUIRED_GATES,'release-author');const claims=REQUIRED_GATES.map(kind=>self.attest({kind,release_id:m.release_id,genesis_sha256:hash,result:'PASS',...times}));const result=checkLaunch(m,self.trust,claims,hash,now);assert.ok(Object.values(result.checks).every(v=>v.status==='OUTSTANDING'));const v4Claims=REQUIRED_GATES.map(kind=>a.attest({kind,release_id:manifest('v4').release_id,genesis_sha256:hash,result:'PASS',...times}));assert.equal(checkLaunch(m,a.trust,v4Claims,hash,now).status,'CANDIDATE_BLOCKED_EXTERNAL_GATES');});
test('v5: signed external gates require reviewed independent organization roster and still prohibit public funds',()=>{const m=manifest(),a=authority();const claims=REQUIRED_GATES.map(kind=>a.attest({kind,release_id:m.release_id,genesis_sha256:hash,result:'PASS',...times,...(kind==='operator_independence'?{operators:[0,1,2,3].map(i=>({organization:'operator-'+i,validator_public_key_hex:String(i+1).repeat(64)})),stake_concentration_reviewed:true}:{})}));const result=checkLaunch(m,a.trust,claims,hash,now);assert.equal(result.status,'EXTERNAL_CANDIDATE_GATES_PRESENT');assert.equal(result.public_funds_allowed,false);assert.equal(result.monetary_enable_toggle,false);});
test('v5: restore rejects old signer state, conflicting signatures and stale authority floor',()=>{const expected={release_id:manifest().release_id,genesis_sha256:hash,validator_public_key_hex:key},a=authority(['signer_backup','signer_floor']);const shared={...expected,...times,fence_domain:'signer-authority',height:'10',round:'2',step:'3',fence_token:'8',sign_bytes_sha256:hash,signature_sha256:key};const backup=a.attest({...shared,kind:'signer_backup'}),floor=a.attest({...shared,kind:'signer_floor'});assert.equal(checkRestore(backup,floor,a.trust,expected,now).automatic_restore,false);for(const patch of [{height:'9'},{round:'1'},{step:'2'},{fence_token:'7'},{sign_bytes_sha256:key},{genesis_sha256:key},{release_id:manifest('v4').release_id}])assert.throws(()=>checkRestore(a.attest({...backup.payload,...patch}),floor,a.trust,expected,now));assert.throws(()=>checkRestore(backup,a.attest({...floor.payload,issued_utc:new Date(now-120000).toISOString()}),a.trust,expected,now),/60 seconds/);});
test('v5: private Comet config binds privileged listeners to loopback, forbids file-validator fallback and never prunes',()=>{const config=cometConfig({sentry_peers:sentries},'v5');for(const port of ['26657','26658','26659','26660'])assert.ok(config.includes('127.0.0.1:'+port));assert.ok(config.includes('proxy_app = "tcp://127.0.0.1:26658"'));/* ADAPTED (kit rehearsal): asserted /operator/FILE_VALIDATOR_IS_FORBIDDEN, a path on the read-only mount where CometBFT 0.38.26 panics at start; the v5 paths are on the container tmpfs and the v4 path is unchanged */assert.ok(!config.includes('/operator/FILE_VALIDATOR'));assert.ok(cometConfig({sentry_peers:sentries}).includes('/operator/FILE_VALIDATOR_IS_FORBIDDEN'));assert.match(config,/^priv_validator_laddr = "tcp:\/\/127\.0\.0\.1:26659"$/m);assert.ok(config.includes('pex = false'));assert.ok(config.includes('unsafe = false'));assert.ok(config.includes('\n[mempool]\n'));assert.match(config,/^recheck = true$/m);assert.ok(config.includes('\n[storage]\n'));assert.match(config,/^discard_abci_responses = false$/m);assert.ok(!/^\s*(?:retain|prune|pruning|discard_abci_responses = true)/m.test(config));assert.ok(!/\[state_?sync\][^[]*enable = true/.test(config));assert.ok(!config.includes('0.0.0.0:2665'+'7'));assert.equal(sha256(Buffer.from(cometConfig({sentry_peers:sentries}))),V4_GOLDEN.comet_config_sha256);assert.equal(cometConfig({sentry_peers:sentries},'v4'),cometConfig({sentry_peers:sentries}));assert.throws(()=>cometConfig({sentry_peers:sentries},'v6'),/engine/);});
test('v5: malformed head timestamp cannot pass a NaN freshness comparison',()=>{assert.throws(()=>checkHealth({chain_id:'time-devnet-v4-test'},{node_info:{network:'time-devnet-v4-test'},sync_info:{latest_block_height:'10',catching_up:false,latest_block_time:'not-a-time'}},v5Status(),now,'v5'),/stale/);});
test('v5: readiness accepts v5 status and rejects stale head, catching-up, wrong chain, GC pressure and uninitialized state',()=>{const settings={chain_id:'time-devnet-v4-test'},status={node_info:{network:settings.chain_id},sync_info:{latest_block_height:'10',latest_block_time:new Date(now).toISOString(),catching_up:false}},app=v5Status();const ready=checkHealth(settings,status,app,now,'v5');assert.equal(ready.authenticated,false);assert.equal(ready.engine,'v5');assert.equal(ready.snapshot_height,'8');assert.equal(ready.public_funds_allowed,false);assert.throws(()=>checkHealth(settings,status,{...app,maintenance:{...app.maintenance,pressure:true}},now,'v5'));assert.throws(()=>checkHealth(settings,{...status,sync_info:{...status.sync_info,catching_up:true}},app,now,'v5'));assert.throws(()=>checkHealth(settings,status,app,now+60000,'v5'));assert.throws(()=>checkHealth({chain_id:'wrong'},status,app,now,'v5'));for(const patch of [{app_version:null},{app_version:'5'},{mode:'mainnet'},{public_launch_allowed:true}])assert.throws(()=>checkHealth(settings,status,{...app,...patch},now,'v5'),/protocol/);});
test('v5: runtime guard requires real pinned genesis and live externally signed lease',async()=>{const{root,a,settings,payload}=await guardSetup();const accepted=await guard(settings,now);assert.equal(accepted.lease.fence_token,'42');assert.equal(accepted.engine,'v5');await assert.rejects(guard({...settings,genesis_sha256:hash},now),/Genesis/);await assert.rejects(guard({...settings,release_id:manifest('v4').release_id},now),/identity/);await assert.rejects(guard({...settings,snapshot_seconds:4},now),/snapshot_seconds/);await assert.rejects(guard({...settings,clock_tolerance_seconds:61},now),/clock_tolerance_seconds/);assert.equal((await guard({...settings,snapshot_seconds:30,clock_tolerance_seconds:30},now)).engine,'v5');await put(root,'operator/lease.json',JSON.stringify(a.attest({...payload,enforcement:'STARTUP_ONLY'})));await assert.rejects(guard(settings,now),/Per-signature/);});

