test('v5: engine mismatch between pinned release, running application and distribution is rejected',async()=>{const settings={chain_id:'time-devnet-v4-test'},status={node_info:{network:settings.chain_id},sync_info:{latest_block_height:'10',latest_block_time:new Date(now).toISOString(),catching_up:false}};const{engine,...v4Status}=v5Status();assert.equal(engine,'v5');assert.equal(checkHealth(settings,status,v4Status,now).engine,undefined);assert.throws(()=>checkHealth(settings,status,v5Status(),now),/engine/);assert.throws(()=>checkHealth(settings,status,v5Status(),now,'v4'),/engine/);assert.throws(()=>checkHealth(settings,status,v4Status,now,'v5'),/engine/);assert.throws(()=>checkHealth(settings,status,v5Status({engine:'v6'}),now,'v5'),/engine/);assert.throws(()=>checkHealth(settings,status,v5Status({engine:'V5'}),now,'v5'),/engine/);assert.throws(()=>checkHealth(settings,status,v5Status(),now,'v6'),/engine/);const{root,nativeDirectory}=await nativeFixture();await assert.rejects(v4.createSdkDistribution({root,nativeDirectory,out:path.join(root,'releases','as-v4')}),/engine/);const v4Root=await v4Fixture();for(const file of CLIENT_FILES)await put(v4Root,file,file.endsWith('.json')?'{}':'// public runtime fixture');const v4Native=path.join(v4Root,'releases','native');await nativeEvidence(v4Native,await v4.createRelease({root:v4Root,out:v4Native,imagePins:pins}));await assert.rejects(createSdkDistribution({root:v4Root,nativeDirectory:v4Native,out:path.join(v4Root,'releases','as-v5')}),/engine/);});
test('v5: version string is checked exactly and matches v5/Cargo.toml',async()=>{assert.equal(ENGINES.v5.version,'time-node-v5 0.10.0 protocol=4 devnet-only publicLaunchAllowed=false');assert.equal(ENGINES.v5.binary,'time-node-v5');assert.equal(checkVersions('v5',ENGINES.v5.version,'0.38.26'),true);for(const wrong of [ENGINES.v4.version,'time-node-v5 0.5.0 protocol=4 devnet-only publicLaunchAllowed=false','time-node-v5 0.6.0 protocol=4 devnet-only publicLaunchAllowed=false','time-node-v5 0.7.0 protocol=4 devnet-only publicLaunchAllowed=false','time-node-v5 0.8.1 protocol=4 devnet-only publicLaunchAllowed=false','time-node-v5 0.10.0 devnet-only publicLaunchAllowed=false','time-node-v5 0.10.0 protocol=5 devnet-only publicLaunchAllowed=false','time-node-v5 0.10.0 protocol=4..5 devnet-only publicLaunchAllowed=false','time-node-v5 0.10.0 protocol=4 rehearsal=5 devnet-only publicLaunchAllowed=false','time-node-v5 0.10.0 protocol=4 devnet-only publicLaunchAllowed=true','x '+ENGINES.v5.version,ENGINES.v5.version+' extra',''])assert.throws(()=>checkVersions('v5',wrong,'0.38.26'),/version/);assert.throws(()=>checkVersions('v5',ENGINES.v5.version,'0.38.25'),/version/);assert.throws(()=>checkVersions('v4',ENGINES.v5.version,'0.38.26'),/version/);assert.equal(checkVersions('v4',ENGINES.v4.version,'0.38.26'),true);assert.throws(()=>checkVersions('v6','x','0.38.26'),/engine/);const cargo=await readFile(here('../v5/Cargo.toml'),'utf8');const version=/^version = "([^"]+)"$/m.exec(cargo)?.[1];assert.ok(version);assert.ok(ENGINES.v5.version.startsWith('time-node-v5 '+version+' protocol=4 '));assert.match(cargo,/^name = "time-node-v5"$/m);});
test('v5: v4 release identity is unchanged by the engine field',async()=>{const frozen=JSON.parse(await readFile(here(FROZEN_V4.file),'utf8'));assert.equal(Object.hasOwn(frozen,'engine'),false);assert.equal(releaseEngine(frozen),'v4');assert.equal(validateRelease(frozen).release_id,FROZEN_V4.release_id);assert.deepEqual(Object.keys(JSON.parse(JSON.stringify(releaseIdentity(frozen)))),V4_IDENTITY_KEYS);assert.equal(sha256(Buffer.from(JSON.stringify(releaseIdentity(frozen)))),FROZEN_V4.release_id);const root=await v4Fixture(),current=await v4.createRelease({root,out:path.join(root,'releases','golden'),imagePins:pins});assert.equal(Object.hasOwn(current,'engine'),false);assert.equal(current.release_id,V4_GOLDEN.release_id);assert.equal(current.sbom_sha256,V4_GOLDEN.sbom_sha256);assert.equal(current.generated_dockerignore_sha256,V4_GOLDEN.generated_dockerignore_sha256);assert.equal(JSON.parse(await readFile(path.join(root,'releases','golden','sbom.spdx.json'),'utf8')).name.startsWith('timecurrency-v4-source-'),true);assert.throws(()=>validateRelease({...frozen,engine:'v5'}),/identity/);for(const engine of ['v4',null,'','V5'])assert.throws(()=>validateRelease({...frozen,engine}),/engine/);const m=manifest();const{engine,...withoutEngine}=m;assert.equal(engine,'v5');assert.notEqual(sha256(Buffer.from(JSON.stringify(releaseIdentity(withoutEngine)))),m.release_id);assert.deepEqual(Object.keys(releaseIdentity(m)).filter(k=>releaseIdentity(m)[k]!==undefined),['schema_version','protocol_version','engine',...V4_IDENTITY_KEYS.slice(2)]);});
test('v5: app launch keeps loopback ABCI, stores state in the ledger volume and passes only validated optional settings',()=>{assert.equal(V5_DB,'/data/ledger/v5-state');const base=['--devnet','--db','/data/ledger/v5-state','--listen','127.0.0.1:26658'];assert.deepEqual(appCommand('v5',{}),['time-node-v5',base]);assert.ok(!appCommand('v5',{})[1].includes('--stay-after-disconnect'));assert.deepEqual(appCommand('v5',{snapshot_seconds:30}),['time-node-v5',[...base,'--snapshot-seconds','30']]);assert.deepEqual(appCommand('v5',{snapshot_seconds:86400}),['time-node-v5',[...base,'--snapshot-seconds','86400']]);for(const value of [4,86401,'30',1.5,-1,null])assert.throws(()=>appCommand('v5',{snapshot_seconds:value}),/snapshot_seconds/);for(const value of [1,30,60])assert.deepEqual(appCommand('v5',{clock_tolerance_seconds:value}),['time-node-v5',[...base,'--clock-tolerance-seconds',String(value)]]);assert.deepEqual(appCommand('v5',{snapshot_seconds:30,clock_tolerance_seconds:45}),['time-node-v5',[...base,'--snapshot-seconds','30','--clock-tolerance-seconds','45']]);assert.ok(!appCommand('v5',{snapshot_seconds:30})[1].includes('--clock-tolerance-seconds'));for(const value of [0,61,600,'30',1.5,-1,null])assert.throws(()=>appCommand('v5',{clock_tolerance_seconds:value}),/clock_tolerance_seconds must be an integer from 1 to 60/);for(const value of [1,30,60])assert.throws(()=>appCommand('v4',{clock_tolerance_seconds:value}),/clock_tolerance_seconds applies only to v5/);assert.deepEqual(appCommand('v4',{}),['time-node-v4',['--devnet','--db','/data/ledger/state.redb','--listen','127.0.0.1:26658']]);assert.throws(()=>appCommand('v4',{snapshot_seconds:30}),/only to v5/);assert.throws(()=>appCommand('v6',{}),/engine/);});
test('v5: exit code 3 after a CometBFT disconnect is reported, never restarted',()=>{assert.deepEqual(childOutcome('app','v5',0),{exitCode:0});assert.throws(()=>childOutcome('app','v5',3),error=>error.exitCode===3&&/code 3/.test(error.message)&&/snapshot/.test(error.message));for(const [kind,engine,code] of [['app','v4',3],['comet','v5',3],['app','v5',1],['app','v5',null]])assert.throws(()=>childOutcome(kind,engine,code),error=>error.exitCode===undefined&&/child process failed/.test(error.message));});
test('v5: a ledger volume holding the other engine\'s state is refused in both directions',async()=>{const temp=()=>mkdtemp(path.join(tmpdir(),'time-ledger-v5-'));const empty=await temp();for(const engine of ['v4','v5'])assert.equal(await checkLedgerVolume(engine,empty),true);const v5Volume=await temp();await put(v5Volume,'v5-state.v5state/snapshot-00000000000000001234','x');await put(v5Volume,'v5-state.history/leaves.bin','x');assert.equal(await checkLedgerVolume('v5',v5Volume),true);await assert.rejects(checkLedgerVolume('v4',v5Volume),/v5 state.*fresh ledger AND consensus volumes/);for(const name of ['state.redb','state.history/leaves.bin']){const v4Volume=await temp();await put(v4Volume,name,'v4');assert.equal(await checkLedgerVolume('v4',v4Volume),true);await assert.rejects(checkLedgerVolume('v5',v4Volume),/v4 state.*new Compose project: fresh ledger AND consensus volumes/);}const dir=await temp();await mkdir(path.join(dir,'state.redb'));await assert.rejects(checkLedgerVolume('v5',dir),/v4 state/);await assert.rejects(checkLedgerVolume('v6',empty),/engine/);});
test('v5: volumes are bound to one engine and one network, and blocks need a matching ledger',async()=>{const temp=()=>mkdtemp(path.join(tmpdir(),'time-volume-v5-'));const settings={genesis_sha256:hash,chain_id:'time-devnet-v4-test'},ledger=await temp(),comet=await temp();const binding=await checkVolumes('v5',settings,{ledger,comet});assert.deepEqual(binding,{schema_version:1,engine:'v5',genesis_sha256:hash,chain_id:'time-devnet-v4-test'});assert.deepEqual(networkBinding('v5',settings),binding);for(const directory of [ledger,comet]){assert.equal(await bindVolume(directory,binding),true);assert.equal(await bindVolume(directory,binding),false);assert.deepEqual(JSON.parse(await readFile(path.join(directory,BINDING_FILE),'utf8')),binding);}await put(comet,'data/blockstore.db/000001.log','blocks');await assert.rejects(checkVolumes('v5',settings,{ledger,comet}),/no binding or state for v5 \(no saved snapshot\)/);await put(ledger,'v5-state.v5state/state-00000000000000000012.snap','snapshot');assert.deepEqual(await checkVolumes('v5',settings,{ledger,comet}),binding);for(const patch of [{genesis_sha256:key},{chain_id:'time-devnet-v4-other'}])for(const view of [{ledger},{comet}])await assert.rejects(checkVolumes('v5',{...settings,...patch},view),/bound to engine v5.*fresh ledger AND consensus volumes/);for(const view of [{ledger},{comet},{ledger,comet}])await assert.rejects(checkVolumes('v4',settings,view),/bound to engine v5/);
 const unbound=await temp();await put(unbound,'data/blockstore.db/000001.log','v4 blocks');await assert.rejects(checkVolumes('v5',settings,{comet:unbound}),/blocks but no v5 network binding/);assert.equal((await checkVolumes('v4',settings,{comet:unbound})).engine,'v4');
 const lost=await temp();await assert.rejects(checkVolumes('v5',settings,{comet,ledger:lost}),/no binding or state for v5/);for(const name of ['v5-state.v5state/partial-00000000000000000012-7.tmp','v5-state.v5state/damaged-state-00000000000000000012.snap','v5-state.v5state/state-12.snap','v5-state.history/leaves.bin']){await put(lost,name,'x');await assert.rejects(checkVolumes('v5',settings,{comet,ledger:lost}),/no saved snapshot/,name);}await put(lost,'v5-state.v5state/state-00000000000000000012.snap','x');assert.equal((await checkVolumes('v5',settings,{comet,ledger:lost})).engine,'v5');
 const v4Ledger=await temp();await put(v4Ledger,'state.redb','v4');await assert.rejects(checkVolumes('v5',settings,{comet,ledger:v4Ledger}),/v4 state/);
 const malformed=await temp();await put(malformed,BINDING_FILE,JSON.stringify({...binding,extra:true}));await assert.rejects(checkVolumes('v5',settings,{ledger:malformed}),/Unreadable volume network binding/);await assert.rejects(checkVolumes('v5',{chain_id:'x'},{ledger}),/Invalid/);});
test('v5: a v5 release is not accepted on a v4 network unless the signed lease names the engine',async()=>{const v4Network=await guardSetup(manifest('v4'));assert.equal(Object.hasOwn(v4Network.payload,'engine'),false);assert.equal((await guard(v4Network.settings,now)).engine,'v4');await put(v4Network.root,'operator/lease.json',JSON.stringify(v4Network.a.attest({...v4Network.payload,engine:'v5'})));await assert.rejects(guard(v4Network.settings,now),/scope mismatch: engine/);const v5=await guardSetup(manifest());assert.equal(v5.payload.engine,'v5');assert.equal((await guard(v5.settings,now)).engine,'v5');const{engine,...withoutEngine}=v5.payload;assert.equal(engine,'v5');for(const lease of [withoutEngine,{...v5.payload,engine:'v4'},{...v5.payload,engine:'V5'}]){await put(v5.root,'operator/lease.json',JSON.stringify(v5.a.attest(lease)));await assert.rejects(guard(v5.settings,now),/scope mismatch: engine/);}});
test('v5: the v5 Compose project and systemd unit never use the v4 project or its volumes',async()=>{const compose=await readFile(here('../deploy/compose.v5.yaml'),'utf8'),v4Compose=await readFile(here('../deploy/compose.yaml'),'utf8'),unit=await readFile(here('../deploy/time-v5.service'),'utf8');assert.equal(/^name: (.+)$/m.exec(compose)?.[1],'time-v5-private-devnet');assert.equal(/^name: (.+)$/m.exec(v4Compose)?.[1],'time-v4-private-devnet');assert.equal(LEDGER_VIEW,'/data/ledger-view');assert.ok(compose.includes('      - ledger:'+LEDGER_VIEW+':ro\n'));assert.ok(!v4Compose.includes(LEDGER_VIEW));for(const line of [/^ExecStart=.*$/m,/^ExecStop=.*$/m]){const command=line.exec(unit)?.[0]??'';assert.ok(command.includes(' --project-name time-v5-private-devnet ')&&command.includes('/deploy/compose.v5.yaml')&&!command.includes('compose.yaml '),command);}assert.match(unit,/^Restart=no$/m);const strip=text=>text.split('\n').filter(line=>!/^\s*#/.test(line)&&!/^name: /.test(line)&&!line.includes(LEDGER_VIEW)&&!line.includes('signer-state')&&!/^ {4}tmpfs: /.test(line)&&!/stop_grace_period|^ {4}init: true$/.test(line)).join('\n');assert.equal(strip(compose),strip(v4Compose));assert.equal((compose.match(/restart: "no"/g)??[]).length,4);assert.match(compose,/^ {4}stop_grace_period: 120s$/m);});
// Service blocks of a Compose file, by name.
const services=compose=>Object.fromEntries([...(compose.slice(compose.indexOf('\nservices:\n'),compose.indexOf('\nnetworks:\n'))+'\nnetworks:\n').matchAll(/\n {2}([a-z]+):\n([\s\S]*?)(?=\n {2}[a-z]+:\n|\nnetworks:)/g)].map(m=>[m[1],m[2]]));
const seconds=block=>Number(/stop_grace_period: ([0-9]+)s/.exec(block)?.[1]??10);
test('v5: stop budgets add up: Node containers act on SIGTERM and the unit outlasts every stop wave',async()=>{const compose=await readFile(here('../deploy/compose.v5.yaml'),'utf8'),unit=await readFile(here('../deploy/time-v5.service'),'utf8'),blocks=services(compose);assert.deepEqual(Object.keys(blocks).sort(),['app','monitor','signer','validator']);for(const name of ['validator','app','monitor','signer'])assert.match(blocks[name],/^ {4}init: true$/m,name+': without an init process a program that handles no SIGTERM itself ignores it as process 1 (tmkms did, and signed on for 30 s)');assert.ok(!/--timeout/.test(unit),'down --timeout overrides every stop_grace_period');const budget=Number(/^TimeoutStopSec=([0-9]+)$/m.exec(unit)?.[1]);assert.equal(seconds(blocks.app),120);const waves=Math.max(seconds(blocks.monitor),seconds(blocks.signer))+seconds(blocks.app)+seconds(blocks.validator);assert.ok(budget>=waves+30,'TimeoutStopSec '+budget+' < stop waves '+waves+' + 30 s');const operator=await readFile(here('../deploy/operator.mjs'),'utf8'),body=operator.slice(operator.indexOf('async function run('));assert.ok(body.indexOf("process.on('SIGTERM',stop)")>=0&&body.indexOf("process.on('SIGTERM',stop)")<body.indexOf('await guard(')&&body.indexOf('await guard(')<body.indexOf('spawn('),'run() must handle SIGTERM before any await');});
test('v5: v5 tests read nothing outside the release context except env-gated exports',async()=>{const directory=here('../v5/tests/'),found=[];for(const file of (await readdir(directory)).filter(name=>name.endsWith('.rs'))){const text=await readFile(new URL(file,directory),'utf8');for(const match of text.matchAll(/CARGO_MANIFEST_DIR/g)){const statement=text.slice(match.index,text.indexOf(';',match.index)),parts=[...statement.matchAll(/join\("([^"]+)"\)/g)].map(m=>m[1]);const relative=path.posix.normalize((statement.includes('.parent()')?'':'v5/')+parts.join('/'));const start=text.lastIndexOf('\nfn ',match.index);found.push({file,relative,gated:/^\nfn \w+\(\) \{\s*if std::env::var\("V5_[A-Z_]+"\)\.is_err\(\) \{\s*return;\s*\}/.test(text.slice(start))});}}assert.ok(found.length>=2);for(const item of found)assert.ok(REQUIRED_FILES.includes(item.relative)||OPTIONAL_FILES.includes(item.relative)||item.relative.startsWith('v5/')||item.gated,JSON.stringify(item));assert.ok(found.some(item=>item.relative==='campaign/lib/genesis.mjs'));assert.ok(found.some(item=>item.relative==='client-v4/account-security.fixture.json'&&item.gated));});
test('v5: optional tools/genesis-v5.mjs is packaged only when present and never in v4',async()=>{assert.deepEqual(OPTIONAL_FILES,['tools/genesis-v5.mjs']);const root=await fixture();const without=await createRelease({root,out:path.join(root,'releases','without'),imagePins:pins});assert.ok(!without.source_files.some(file=>file.path==='tools/genesis-v5.mjs'));await put(root,'tools/genesis-v5.mjs','export const genesis = 1;\n');const withFile=await createRelease({root,out:path.join(root,'releases','with'),imagePins:pins});assert.ok(withFile.source_files.some(file=>file.path==='tools/genesis-v5.mjs'));assert.notEqual(without.release_id,withFile.release_id);await put(root,'tools/genesis-v5.mjs','// -----BEGIN '+'PRIVATE KEY-----');await assert.rejects(collectReleaseFiles(root),/credential/);const v4Root=await v4Fixture();await put(v4Root,'tools/genesis-v5.mjs','export const genesis = 1;\n');const v4Release=await v4.createRelease({root:v4Root,out:path.join(v4Root,'releases','golden'),imagePins:pins});assert.equal(v4Release.release_id,V4_GOLDEN.release_id);});
// Port of options() in v5/src/main.rs for time-node-v5 0.7.0, which 0.8.0 did not change. The 0.5.0 port came from the independent
// review; --clock-tolerance-seconds (whole number 1..60, default 30, once) is ported from the behavior the
// engine session described. The four state-sync and pruning flags are ported from the landed code of branch
// fast-join (v5/src/main.rs, `whole_number`: no sign, no leading zero), and --stop-after-height (a whole number
// from 1 to 2^63 - 1, once, not with --audit) from the landed code of branch upgrade-engine (commit 58a78ea,
// v5/src/main.rs `options`), whose own test accepts and refuses the same spellings as this port.
function v5Whole(it,flag){const v=it.next();if(v.done)throw Error(flag+' needs a number');if(!/^(?:0|[1-9][0-9]*)$/.test(v.value)||BigInt(v.value)>18446744073709551615n)throw Error(flag+' must be a whole number');return BigInt(v.value);}
function v5Parse(args){let devnet=false,db,listen,audit=false,snap,clock,stay=false,syncBlocks,syncKept,syncMax,keep,stopAfter;const it=args[Symbol.iterator]();for(let n=it.next();!n.done;n=it.next()){const arg=n.value;if(arg==='--audit'&&!audit)audit=true;else if(arg==='--devnet'&&!devnet)devnet=true;else if(arg==='--stay-after-disconnect'&&!stay)stay=true;else if(arg==='--db'&&db===undefined){const v=it.next();if(v.done)throw Error('--db needs a path');db=v.value;}else if(arg==='--listen'&&listen===undefined){const v=it.next();if(v.done)throw Error('--listen needs an address');listen=v.value;}else if(arg==='--snapshot-seconds'&&snap===undefined){const v=it.next();if(v.done)throw Error('--snapshot-seconds needs a number');if(!/^\+?[0-9]+$/.test(v.value))throw Error('--snapshot-seconds must be a whole number');const x=Number(v.value);if(x<5||x>86400)throw Error('--snapshot-seconds must be between 5 and 86400');snap=x;}else if(arg==='--clock-tolerance-seconds'&&clock===undefined){const v=it.next();if(v.done)throw Error('--clock-tolerance-seconds needs a number');if(!/^\+?[0-9]+$/.test(v.value))throw Error('--clock-tolerance-seconds must be a whole number');const x=Number(v.value);if(x<1||x>60)throw Error('--clock-tolerance-seconds must be between 1 and 60');clock=x;}else if(arg==='--state-sync-snapshot-blocks'&&syncBlocks===undefined){const x=v5Whole(it,arg);if(x!==0n&&(x<10n||x>1000000n))throw Error('--state-sync-snapshot-blocks must be 0 (no snapshots for peers) or between 10 and 1000000');syncBlocks=x;}else if(arg==='--state-sync-snapshots-kept'&&syncKept===undefined){const x=v5Whole(it,arg);if(x<1n||x>10n)throw Error('--state-sync-snapshots-kept must be between 1 and 10');syncKept=x;}else if(arg==='--state-sync-max-mib'&&syncMax===undefined){const x=v5Whole(it,arg);if(x<4n||x>400000n)throw Error('--state-sync-max-mib must be between 4 and 400000');syncMax=x;}else if(arg==='--keep-blocks'&&keep===undefined){const x=v5Whole(it,arg);if(x!==0n&&(x<2000000n||x>1000000000000n))throw Error('--keep-blocks must be 0 (keep every block) or at least 2000000');keep=x;}else if(arg==='--stop-after-height'&&stopAfter===undefined){const x=v5Whole(it,arg);if(x<1n||x>9223372036854775807n)throw Error('--stop-after-height must be a block height, at least 1');stopAfter=x;}else throw Error('unsupported or duplicate argument: '+arg);}if(!devnet)throw Error('--devnet is required');if(!db)throw Error('--db is required');if((syncBlocks??0n)===0n&&syncKept!==undefined)throw Error('--state-sync-snapshots-kept needs --state-sync-snapshot-blocks');if(audit&&(syncBlocks!==undefined||syncKept!==undefined||syncMax!==undefined||keep!==undefined))throw Error('--audit takes no state-sync or pruning setting');if(audit&&stopAfter!==undefined)throw Error('--audit takes no --stop-after-height');return{db,listen:listen??'127.0.0.1:26658',audit,snapshot_seconds:snap??120,clock_tolerance_seconds:clock??30,stay,state_sync_snapshot_blocks:syncBlocks??0n,state_sync_snapshots_kept:syncKept??2n,state_sync_max_mib:syncMax??16384n,keep_blocks:keep??0n,stop_after_height:stopAfter??null};}
test('v5: every launch command the guard admits parses under the time-node-v5 0.10.0 argument parser',()=>{assert.equal(ENGINES.v5.version,'time-node-v5 0.10.0 protocol=4 devnet-only publicLaunchAllowed=false');for(const [settings,expected] of [[{state_sync_snapshot_blocks:0},{state_sync_snapshot_blocks:0n}],[{state_sync_snapshot_blocks:10},{state_sync_snapshot_blocks:10n}],[{state_sync_snapshot_blocks:1000000,state_sync_snapshots_kept:1},{state_sync_snapshot_blocks:1000000n,state_sync_snapshots_kept:1n}],[{state_sync_snapshot_blocks:1000,state_sync_snapshots_kept:10},{state_sync_snapshot_blocks:1000n,state_sync_snapshots_kept:10n}],[{state_sync_max_mib:4},{state_sync_max_mib:4n}],[{state_sync_max_mib:400000},{state_sync_max_mib:400000n}],[{keep_blocks:0},{keep_blocks:0n}],[{keep_blocks:2000000},{keep_blocks:2000000n}],[{keep_blocks:1000000000000},{keep_blocks:1000000000000n}],[{stop_after_height:1},{stop_after_height:1n}],[{stop_after_height:Number.MAX_SAFE_INTEGER},{stop_after_height:BigInt(Number.MAX_SAFE_INTEGER)}],[{snapshot_seconds:30,clock_tolerance_seconds:45,state_sync_snapshot_blocks:1000,state_sync_snapshots_kept:2,state_sync_max_mib:16384,keep_blocks:2000000,stop_after_height:77},{snapshot_seconds:30,clock_tolerance_seconds:45,state_sync_snapshot_blocks:1000n,state_sync_snapshots_kept:2n,state_sync_max_mib:16384n,keep_blocks:2000000n,stop_after_height:77n}]]){const parsed=v5Parse(appCommand('v5',settings)[1]);for(const [name,value] of Object.entries({state_sync_snapshot_blocks:0n,state_sync_snapshots_kept:2n,state_sync_max_mib:16384n,keep_blocks:0n,stop_after_height:null,...expected}))assert.equal(parsed[name],value,JSON.stringify(settings)+' '+name);}for(const [flag,values] of [['--state-sync-snapshot-blocks',['9','1000001','01','+10','x','']],['--state-sync-max-mib',['3','400001','04']],['--keep-blocks',['1','1999999','1000000000001']],['--stop-after-height',['0','-1','+1','01','1.0','1.5','1e3',' 1','','next','9223372036854775808','18446744073709551616']]])for(const value of values)assert.throws(()=>v5Parse(['--devnet','--db','x',flag,value]),new RegExp(flag.slice(2)),flag+' '+value);assert.throws(()=>v5Parse(['--devnet','--db','x','--state-sync-snapshots-kept','2']),/needs --state-sync-snapshot-blocks/);assert.throws(()=>v5Parse(['--devnet','--db','x','--stop-after-height','5','--stop-after-height','5']),/duplicate/);assert.throws(()=>v5Parse(['--devnet','--db','x','--audit','--stop-after-height','5']),/--audit takes no --stop-after-height/);assert.equal(v5Parse(['--devnet','--db','x','--stop-after-height','9223372036854775807']).stop_after_height,9223372036854775807n);assert.equal(v5Parse(['--devnet','--db','x','--stop-after-height','77','--keep-blocks','3000000','--snapshot-seconds','30']).keep_blocks,3000000n);for(const [settings,snapshot,clock] of [[{},120,30],[{snapshot_seconds:5},5,30],[{snapshot_seconds:86400},86400,30],[{clock_tolerance_seconds:1},120,1],[{clock_tolerance_seconds:60},120,60],[{snapshot_seconds:30,clock_tolerance_seconds:45},30,45]]){const parsed=v5Parse(appCommand('v5',settings)[1]);assert.equal(parsed.db,V5_DB);assert.equal(parsed.listen,'127.0.0.1:26658');assert.equal(parsed.snapshot_seconds,snapshot);assert.equal(parsed.clock_tolerance_seconds,clock);assert.equal(parsed.stay,false);}const base=['--devnet','--db','x'];for(const value of ['0','61','600','-1','1.5','x',''])assert.throws(()=>v5Parse([...base,'--clock-tolerance-seconds',value]),/clock-tolerance-seconds/,value);assert.throws(()=>v5Parse([...base,'--clock-tolerance-seconds']),/needs a number/);assert.throws(()=>v5Parse([...base,'--clock-tolerance-seconds','30','--clock-tolerance-seconds','30']),/duplicate/);for(const value of [0,61])assert.throws(()=>appCommand('v5',{clock_tolerance_seconds:value}),/clock_tolerance_seconds/);});
test('v5: every module and asset the gateway imports is in both distributions',async()=>{for(const file of ['client-v4/account-security.mjs','client-v4/own-node.mjs'])assert.ok(v4.CLIENT_FILES.includes(file)&&CLIENT_FILES.includes(file),file);const root=fileURLToPath(here('../'));if(!await lstat(path.join(root,'client-v4','server.mjs')).then(()=>true,()=>false)){for(const file of CLIENT_FILES.filter(f=>f.startsWith('client-v4/')||f.startsWith('web-v4/')))await assert.rejects(lstat(path.join(root,file)),{code:'ENOENT'});return;}const seen=new Set(),queue=['deploy/gateway/start.mjs'];while(queue.length){const file=queue.pop();if(seen.has(file))continue;seen.add(file);const text=await readFile(path.join(root,file),'utf8');for(const match of text.matchAll(/(?:\bfrom\s*|\bimport\s*\(\s*|\bnew URL\(\s*)(['"])(\.{1,2}\/[^'"]*)\1/g)){if(match[2].endsWith('/'))continue;const target=path.posix.normalize(path.posix.join(path.posix.dirname(file),match[2]));if(/\.m?js$/.test(target))queue.push(target);else seen.add(target);}}for(const file of ['client-v4/server.mjs','client-v4/server-auth.mjs','client-v4/account-security.mjs','client-v4/own-node.mjs','web-v4/shared/verifier/timecurrency_verifier_v4_bg.wasm'])assert.ok(seen.has(file),file);for(const [name,list] of [['v4',v4.CLIENT_FILES],['v5',CLIENT_FILES]])for(const file of seen)assert.ok(list.includes(file),name+' distribution lacks '+file);});
