test('v5: Dockerfile.v5 builds time-node-v5 locked with the pinned toolchain and the same CometBFT build',async()=>{const file=await readFile(here('../deploy/Dockerfile.v5'),'utf8');for(const line of ['ARG RUST_IMAGE','ARG GO_IMAGE','ARG RUNTIME_IMAGE','FROM ${RUST_IMAGE} AS rustbuild','FROM ${GO_IMAGE} AS gobuild','FROM ${RUNTIME_IMAGE} AS runtime','COPY v4 ./v4','COPY v5 ./v5','COPY v2 ./v2','COPY --from=rustbuild /source/v5/target/release/time-node-v5 /usr/local/bin/time-node-v5','COPY --from=gobuild /out/cometbft /usr/local/bin/cometbft','USER 10001:10001','STOPSIGNAL SIGTERM','ENTRYPOINT ["node","/opt/time/deploy/operator.mjs"]'])assert.ok(file.split('\n').includes(line),line);assert.equal(file.match(/grep -E '\^\[-a-zA-Z0-9\.\/:_\]\+@sha256:\[a-f0-9\]\{64\}\$'/g)?.length,3);for(const fragment of ['test "$(rustc --version | cut -d \' \' -f2)" = 1.99.1','cargo fetch --manifest-path v5/Cargo.toml --locked','cargo build --manifest-path v5/Cargo.toml --release --frozen --bin time-node-v5','= go1.27.3','"Sum": "h1:MIPYgOSvyyiN1jo3SZljKy4ZXqs896aQnj3pQFfUmaE="','"Hash": "94d77f9f51a72e2b7d832798859f6222f08028f8"','go build -mod=readonly -trimpath','sha256sum --check /locked.sha256'])assert.ok(file.includes(fragment),fragment);assert.ok(!/^FROM [^$]/m.test(file));assert.ok(!file.includes('time-node-v4'));const runs=file.split('\n').filter(line=>line.startsWith('RUN '));const cargo=runs.filter(line=>line.includes('cargo build')),go=runs.filter(line=>/\bgo build\b/.test(line));assert.equal(cargo.length,1);assert.equal(go.length,1);assert.ok(/--frozen|--offline/.test(cargo[0])&&!/cargo fetch|rustup/.test(cargo[0]),cargo[0]);assert.match(file,/^ENV CARGO_NET_OFFLINE=true$/m);assert.ok(go[0].startsWith('RUN GOPROXY=off ')&&go[0].includes('-mod=readonly')&&!/go mod download|go get/.test(go[0]),go[0]);assert.ok(file.indexOf('cargo fetch --manifest-path v5/Cargo.toml')<file.indexOf(cargo[0]));});
