test('v5: exit code 4 is reported with its three causes and what to install, never restarted',()=>{const outcome=settings=>{try{childOutcome('app','v5',4,settings);}catch(error){return error;}assert.fail('exit code 4 was accepted');};const plain=outcome();assert.equal(plain.exitCode,4);assert.match(plain.message,/^time-node-v5 exited with code 4: it stopped at a height on purpose and its state is saved and valid\. Delete nothing; nothing restarts automatically\./);for(const line of ['STOPPED FOR UPGRADE: the chain now runs a protocol version this release does not implement. Install the release that implements it','obtain signer leases for that release','STOPPED AS ASKED: the height in stop_after_height was reached.','remove stop_after_height from the settings','STOPPED AT A SWITCH: a decided block carries an emergency switch','Install the fix release'])assert.ok(plain.message.includes(line),line);assert.ok(outcome({stop_after_height:1234567}).message.includes('STOPPED AS ASKED: the height in stop_after_height was reached (these settings carry stop_after_height 1234567).'));assert.equal(outcome({}).message,plain.message);for(const [kind,engine,code] of [['app','v4',4],['comet','v5',4],['comet','v4',4],['app','v5',2],['app','v5',5],['app','v5',-4],['app','v5','4']])assert.throws(()=>childOutcome(kind,engine,code),error=>error.exitCode===undefined&&/child process failed/.test(error.message),kind+engine+code);assert.throws(()=>childOutcome('app','v5',3),error=>error.exitCode===3);assert.deepEqual(childOutcome('app','v5',0,{stop_after_height:5}),{exitCode:0});});
