// The browser side: what the wallet and shop pages load, through their script and stylesheet tags and every module
// import, with the gateway's /sdk/ routes (client-v4/server.mjs serveStatic) mapped to their files.
test('v5: every module and asset the wallet and shop pages load is in both distributions',async()=>{const root=fileURLToPath(here('../'));if(!await lstat(path.join(root,'web-v4','wallet','index.html')).then(()=>true,()=>false))return;const SDK={'/sdk/proof-verifier.js':'client-v4/proof-verifier.mjs','/sdk/time-sdk.js':'client-v4/time-sdk.js','/sdk/light-client.mjs':'client-v4/light-client.mjs','/sdk/account-security.mjs':'client-v4/account-security.mjs'};const seen=new Set();for(const role of ['wallet','merchant']){const base='web-v4/'+role;const resolve=(from,spec)=>{if(SDK[spec])return SDK[spec];if(spec.startsWith('/sdk/'))throw new Error(from+' loads '+spec+', which the gateway does not serve');if(spec.startsWith('/web-v4/shared/'))return spec.slice(1);if(spec.startsWith('/'))return base+spec;if(spec.startsWith('./')||spec.startsWith('../'))return path.posix.normalize(path.posix.join(path.posix.dirname(from),spec));return null;};const queue=(await readdir(path.join(root,base))).filter(f=>f.endsWith('.html')).map(f=>base+'/'+f);while(queue.length){const file=queue.pop();if(seen.has(file))continue;seen.add(file);if(!/\.(html|m?js)$/.test(file))continue;const text=await readFile(path.join(root,file),'utf8');const specs=file.endsWith('.html')?[...text.matchAll(/<script\b[^>]*\bsrc="([^"]+)"/g),...text.matchAll(/<link\b[^>]*\bhref="([^"]+)"/g)].map(m=>m[1]):[...text.matchAll(/(?:\bfrom\s*|\bimport\s*\(\s*|\bnew URL\(\s*)(['"])([^'"]+)\1/g)].map(m=>m[2]);for(const spec of specs){const target=resolve(file,spec);if(target)queue.push(target);}}}for(const file of ['web-v4/wallet/app.js','web-v4/wallet/security-ui.mjs','web-v4/wallet/security-flows.mjs','client-v4/account-security.mjs','client-v4/proof-verifier.mjs','web-v4/merchant/app.js'])assert.ok(seen.has(file),file);for(const [name,list] of [['v4',v4.CLIENT_FILES],['v5',CLIENT_FILES]])for(const file of seen)assert.ok(list.includes(file),name+' distribution lacks '+file+', which a page loads');});
// Found by the kit rehearsal on AWS (campaign/README.md, "The deployment kit, rehearsed"). CometBFT 0.38.26's
// `cometbft start` (node.DefaultNewNode) loads or writes a file validator key before it looks at
// priv_validator_laddr and panics when it cannot write it. The v5 configuration puts that unused key on the
// validator container's tmpfs: never on /operator (read-only, where it panicked) and never on a volume.
test('v5: the file validator key CometBFT 0.38 writes at start goes to the validator container tmpfs, never to /operator or a volume',async()=>{const config=cometConfig({sentry_peers:sentries},'v5'),compose=await readFile(here('../deploy/compose.v5.yaml'),'utf8'),blocks=services(compose);const value=name=>JSON.parse(new RegExp('^'+name+' = (.+)$','m').exec(config)?.[1]??'null');assert.equal(value('priv_validator_key_file'),V5_UNUSED_PRIVVAL.key);assert.equal(value('priv_validator_state_file'),V5_UNUSED_PRIVVAL.state);for(const file of Object.values(V5_UNUSED_PRIVVAL)){assert.ok(file.startsWith('/tmp/'),file);assert.ok(!file.startsWith('/operator/')&&!file.startsWith('/data/'),file);}assert.match(blocks.validator,/^ {4}tmpfs: \["\/tmp:rw,noexec,nosuid,size=32m"\]$/m);assert.match(blocks.validator,/^ {4}read_only: true$/m);assert.equal(value('priv_validator_laddr'),'tcp://127.0.0.1:26659');assert.equal((config.match(/^priv_validator_key_file = /gm)??[]).length,1);assert.ok(cometConfig({sentry_peers:sentries}).includes('priv_validator_key_file = "/operator/FILE_VALIDATOR_IS_FORBIDDEN"'),'the v4 output is unchanged');});
// Found by the kit rehearsal: the signer container had a read-only root and only the read-only /signer mount, so no
// signer could keep its record of what it last signed. The v5 Compose file gives it a volume of its own for that.
test('v5: the signer has a writable volume of its own for its anti-double-sign state, mounted in no other container',async()=>{const compose=await readFile(here('../deploy/compose.v5.yaml'),'utf8'),blocks=services(compose);assert.match(blocks.signer,/^ {6}- signer-state:\/signer-state$/m);assert.match(blocks.signer,/^ {6}- \$\{SIGNER_CONFIG:\?set signer enrollment directory\}:\/signer:ro$/m);assert.match(blocks.signer,/^ {4}read_only: true$/m);for(const name of ['validator','app','monitor'])assert.ok(!blocks[name].includes('signer-state')&&!blocks[name].includes('SIGNER_CONFIG'),name);const declared=compose.slice(compose.lastIndexOf('\nvolumes:\n'));assert.match(declared,/^ {2}signer-state:$/m);const v4Compose=await readFile(here('../deploy/compose.yaml'),'utf8');assert.ok(!v4Compose.includes('signer-state'),'the v4 Compose file is unchanged');const readme=await readFile(here('../deploy/README.md'),'utf8');assert.match(readme,/`signer-state`/);});
// Found by the kit rehearsal on AWS: `tmpfs: [/tmp:rw,noexec,nosuid,size=32m]` is a YAML flow sequence, so its commas
// make four entries ("/tmp:rw", "noexec", "nosuid", "size=32m") and Docker refused to create the validator container
// ("invalid mount path: 'noexec' mount path must be absolute"); `docker compose config` accepts it. Quoted, it is one.
test('v5: each tmpfs of the Compose file is one entry with its options, as YAML reads a flow sequence',async()=>{const flow=text=>{const items=[];let item='',quoted=false;for(const c of text){if(c==='"'){quoted=!quoted;continue;}if(c===','&&!quoted){items.push(item.trim());item='';continue;}item+=c;}items.push(item.trim());return items;};const entries=compose=>[...compose.matchAll(/^ {4}tmpfs: \[(.*)\]$/gm)].map(m=>flow(m[1]));const v5=entries(await readFile(here('../deploy/compose.v5.yaml'),'utf8')),v4=entries(await readFile(here('../deploy/compose.yaml'),'utf8'));assert.equal(v5.length,2);for(const list of v5){assert.deepEqual(list,['/tmp:rw,noexec,nosuid,size=32m']);assert.ok(list.every(x=>x.startsWith('/')));}assert.deepEqual(v4[0],['/tmp:rw','noexec','nosuid','size=32m'],'the v4 Compose file is unchanged and keeps the defect (a finding)');assert.ok(v4[0].some(x=>!x.startsWith('/')));});
// Found by the kit rehearsal on AWS (campaign tc-v5-kit-4): after its signer had gone, CometBFT did not end on SIGTERM,
// Compose killed the container after 30 s, and the launcher's process lock stayed: every later start was refused.
test('v5: a stop of the consensus launcher ends CometBFT within GUARD_KILL_MS, so that the launcher itself removes its lock',async()=>{const{stopChild,GUARD_KILL_MS}=await import('../deploy/operator.mjs');const timers=[],after=(fn,ms)=>{timers.push({fn,ms});return{unref(){}};};const child=()=>{const c={exitCode:null,signalCode:null,signals:[],kill(signal){this.signals.push(signal);}};return c;};
const comet=child();assert.equal(stopChild(comet,{hardKill:true,after}),true);assert.deepEqual(comet.signals,['SIGTERM']);assert.equal(timers.length,1);assert.equal(timers[0].ms,GUARD_KILL_MS);assert.ok(GUARD_KILL_MS<30000,'before Compose\'s stop_grace_period of the validator');
stopChild(comet,{hardKill:true,after});assert.equal(timers.length,1,'one kill is armed however often the stop is asked');timers[0].fn();assert.deepEqual(comet.signals,['SIGTERM','SIGTERM','SIGKILL']);
const ended=child();stopChild(ended,{hardKill:true,after});ended.exitCode=0;timers.at(-1).fn();assert.deepEqual(ended.signals,['SIGTERM'],'a child that ended is not killed');
const node=child();const before=timers.length;stopChild(node,{hardKill:false,after});assert.equal(timers.length,before,'the node is never killed: it finishes its snapshot');assert.deepEqual(node.signals,['SIGTERM']);
assert.equal(stopChild(undefined,{hardKill:true,after}),false);const gone=child();gone.signalCode='SIGTERM';assert.equal(stopChild(gone,{hardKill:true,after}),false);
const operator=await readFile(here('../deploy/operator.mjs'),'utf8'),body=operator.slice(operator.indexOf('async function run('));assert.match(body,/const stop=\(\)=>\{stopping=true;stopChild\(child,\{hardKill:hardStop\}\);\};/);assert.match(body,/hardStop=kind==='comet'&&engine==='v5';/);const compose=await readFile(here('../deploy/compose.v5.yaml'),'utf8'),blocks=services(compose);assert.ok(seconds(blocks.validator)*1000>GUARD_KILL_MS+5000,'the launcher has time to remove its lock before Compose kills the container');});
// Found by the kit rehearsal on AWS (campaign tc-v5-kit-4): systemd skips ExecStop when the main process fails, so the
// containers of a failed run stayed, and a signer left running in a dead network namespace failed every later start.
test('v5: the unit removes the stack after every run, also one that failed by itself',async()=>{const unit=await readFile(here('../deploy/time-v5.service'),'utf8');const down='/usr/bin/docker compose --project-name time-v5-private-devnet --file /opt/time-v5/context/deploy/compose.v5.yaml down';assert.equal(/^ExecStop=(.*)$/m.exec(unit)?.[1],down);assert.equal(/^ExecStopPost=(.*)$/m.exec(unit)?.[1],down);assert.ok(!/^ExecStopPost=.*\s(?:-v|--volumes|--timeout)(?:\s|=|$)/m.test(unit),'the volumes are kept and every grace period applies');assert.match(unit,/^Restart=no$/m);const v4=await readFile(here('../deploy/time-v4.service'),'utf8');assert.ok(!v4.includes('ExecStopPost'),'the v4 unit is unchanged');});
